    if (!(await this.prisma.user.count({ where: { id } })))
      throw new NotFoundException('Account not found');
    const where = { ownerId: id };
    const [items, total] = await this.prisma.$transaction([
      this.prisma.workflow.findMany({
        where,
        select: {
          id: true,
          name: true,
          status: true,
          active: true,
          updatedAt: true,
        },
