import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '@app/database';
import { AccountAdministrationPort } from '../../application/ports/account-administration.port';
import type { AccountChange } from '../../application/ports/account-administration.port';

export const accountSummarySelect = {
  id: true,
  name: true,
  email: true,
  role: true,
  isActive: true,
  revision: true,
  createdAt: true,
  updatedAt: true,
} as const;

function reasonValue(reason: string) {
  const value = reason.trim();
  if (value.length < 5 || value.length > 500)
    throw new BadRequestException('Reason must contain 5–500 characters');
  return value;
}

@Injectable()
export class PrismaAccountAdministration extends AccountAdministrationPort {
  constructor(private readonly prisma: PrismaService) {
    super();
  }

  async change(input: AccountChange) {
    const reason = reasonValue(input.reason);
    return this.prisma.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT pg_advisory_xact_lock(7261101)::text`;
      await tx.$queryRaw`SELECT id FROM users WHERE id IN (${input.actorId}::uuid, ${input.targetId}::uuid) ORDER BY id FOR UPDATE`;
      const actor = await tx.user.findUnique({ where: { id: input.actorId } });
      if (!actor?.isActive || actor.role !== 'ADMIN')
        throw new ForbiddenException('Admin access required');
      const target = await tx.user.findUnique({
        where: { id: input.targetId },
        select: accountSummarySelect,
      });
      if (!target) throw new NotFoundException('Account not found');
      if (input.actorId === target.id)
        throw new ConflictException({
          code: 'SELF_ADMIN_CHANGE_FORBIDDEN',
          message: 'Cannot change your own role or account status',
        });
      if (target.revision !== input.expectedRevision)
        throw new ConflictException({
          code: 'STALE_REVISION',
          message: 'Account changed; reload before continuing',
        });
      const role = input.role ?? target.role;
      const isActive = input.isActive ?? target.isActive;
      if (input.role === 'ADMIN' && target.role !== 'ADMIN' && !target.isActive)
        throw new ConflictException({
          code: 'TARGET_USER_INACTIVE',
          message: 'Reactivate the account before granting Admin',
        });
      if (role === target.role && isActive === target.isActive)
        return { ...target, auditEventId: null };
      if (
        target.role === 'ADMIN' &&
        target.isActive &&
        (role !== 'ADMIN' || !isActive)
      ) {
        if (
          (await tx.user.count({
            where: { role: 'ADMIN', isActive: true, id: { not: target.id } },
          })) === 0
        ) {
          throw new ConflictException({
            code: 'LAST_ACTIVE_ADMIN',
            message: 'At least one active Admin must remain',
          });
        }
      }
      const updated = await tx.user.update({
        where: { id: target.id },
        data: {
          role,
          isActive,
          revision: { increment: 1 },
          sessionVersion: { increment: 1 },
        },
      });
      const audit = await tx.adminAuditEvent.create({
        data: {
          actorType: 'ADMIN',
          actorId: actor.id,
          targetType: 'USER',
          targetId: target.id,
          action:
            role !== target.role
              ? 'USER_ROLE_CHANGED'
              : isActive
                ? 'USER_REACTIVATED'
                : 'USER_SUSPENDED',
          reason,
          before: { role: target.role, isActive: target.isActive },
          after: { role, isActive },
        },
      });
      await tx.sessionRevocation.create({
        data: { userId: target.id, sessionVersion: updated.sessionVersion },
      });
      const summary = await tx.user.findUniqueOrThrow({
        where: { id: target.id },
        select: accountSummarySelect,
      });
      return { ...summary, auditEventId: audit.id };
    });
  }

  async bootstrap(email: string, reason: string) {
    const normalizedReason = reasonValue(reason);
    return this.prisma.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT pg_advisory_xact_lock(7261101)::text`;
      if (await tx.user.count({ where: { role: 'ADMIN', isActive: true } }))
        throw new ConflictException(
          'An active Admin already exists; use account administration',
        );
      const target = await tx.user.findUnique({
        where: { email: email.trim().toLowerCase() },
      });
      if (!target?.isActive)
        throw new NotFoundException(
          'An active, registered account is required',
        );
      const user = await tx.user.update({
        where: { id: target.id },
        data: {
          role: 'ADMIN',
          revision: { increment: 1 },
          sessionVersion: { increment: 1 },
        },
        select: accountSummarySelect,
      });
      const audit = await tx.adminAuditEvent.create({
        data: {
          actorType: 'SYSTEM',
          targetType: 'USER',
          targetId: target.id,
          action: 'ADMIN_BOOTSTRAPPED',
          reason: normalizedReason,
          before: { role: target.role, isActive: target.isActive },
          after: { role: 'ADMIN', isActive: true },
        },
      });
      await tx.sessionRevocation.create({
        data: { userId: target.id, sessionVersion: target.sessionVersion + 1 },
      });
      return { ...user, auditEventId: audit.id };
    });
  }
}
import {
  BadRequestException,
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '@app/database';
import {
  ChangeConnectorPolicyParams,
  ConnectorPolicyPort,
  ConnectorPolicySnapshot,
} from '../../application/ports/connector-policy.port';

@Injectable()
export class PrismaConnectorPolicyRepository extends ConnectorPolicyPort {
  constructor(private readonly prisma: PrismaService) {
    super();
  }

  async getPolicy(connectorId: string): Promise<ConnectorPolicySnapshot> {
    const policy = await this.prisma.connectorPolicy.findUnique({
      where: { connectorId },
    });
    if (!policy) {
      return {
        connectorId,
        allowNewCredentials: true,
        revision: 0,
        updatedAt: new Date(),
      };
    }
    return {
      connectorId: policy.connectorId,
      allowNewCredentials: policy.allowNewCredentials,
      revision: policy.revision,
      updatedAt: policy.updatedAt,
    };
  }

  async assertCanCreateCredential(connectorId: string): Promise<void> {
    const policy = await this.getPolicy(connectorId);
    if (!policy.allowNewCredentials) {
      throw new ConflictException({
        code: 'CONNECTOR_NEW_CREDENTIALS_DISABLED',
        message:
          'New credentials for this connector have been disabled by platform administrator',
      });
    }
  }

  async changePolicy(
    params: ChangeConnectorPolicyParams,
  ): Promise<ConnectorPolicySnapshot> {
    const reason = params.reason?.trim();
    if (!reason || reason.length < 5 || reason.length > 500) {
      throw new BadRequestException('Reason must contain 5–500 characters');
    }

    return this.prisma.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT pg_advisory_xact_lock(7261102)::text`;

      const connector = await tx.connector.findUnique({
        where: { id: params.connectorId },
      });
      if (!connector) {
        throw new NotFoundException('Connector not found');
      }

      const current = await tx.connectorPolicy.findUnique({
        where: { connectorId: params.connectorId },
      });

      const currentAllow = current ? current.allowNewCredentials : true;
      const currentRevision = current ? current.revision : 0;

      if (currentRevision !== params.expectedRevision) {
        throw new ConflictException({
          code: 'STALE_REVISION',
          message: 'Policy changed; reload before continuing',
        });
      }

      if (currentAllow === params.allowNewCredentials) {
        return {
          connectorId: params.connectorId,
          allowNewCredentials: currentAllow,
          revision: currentRevision,
          updatedAt: current?.updatedAt ?? new Date(),
        };
      }

      const updated = await tx.connectorPolicy.upsert({
        where: { connectorId: params.connectorId },
        create: {
          connectorId: params.connectorId,
          allowNewCredentials: params.allowNewCredentials,
          revision: currentRevision + 1,
        },
        update: {
          allowNewCredentials: params.allowNewCredentials,
          revision: currentRevision + 1,
        },
      });

      await tx.adminAuditEvent.create({
        data: {
          actorType: 'ADMIN',
          actorId: params.adminId,
          targetType: 'CONNECTOR',
          targetId: params.connectorId,
          action: 'CONNECTOR_POLICY_CHANGED',
          reason,
          before: {
            allowNewCredentials: currentAllow,
            revision: currentRevision,
          },
          after: {
            allowNewCredentials: params.allowNewCredentials,
            revision: updated.revision,
          },
        },
      });

      return {
        connectorId: updated.connectorId,
        allowNewCredentials: updated.allowNewCredentials,
        revision: updated.revision,
        updatedAt: updated.updatedAt,
      };
    });
  }
}
import { Injectable } from '@nestjs/common';
import { PrismaService } from '@app/database';
import { NodeTypePolicyPort } from '../../application/ports/node-type-policy.port';
import {
  ChangeNodeTypeStatusParams,
  NodeTypePolicyError,
  NodeTypePolicySnapshot,
  planNodeTypeStatusChange,
} from '../../domain/node-type-policy';

@Injectable()
export class PrismaNodeTypePolicyRepository extends NodeTypePolicyPort {
  constructor(private readonly prisma: PrismaService) {
    super();
  }
  async isExecutionAllowed(key: string): Promise<boolean> {
    const policy = await this.prisma.nodeTypePolicy.findUnique({
      where: { nodeTypeKey: key },
      select: { isExecutionAllowed: true },
    });
    return policy?.isExecutionAllowed ?? true;
  }
  changeStatus(
    params: ChangeNodeTypeStatusParams,
  ): Promise<NodeTypePolicySnapshot> {
    return this.prisma.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT pg_advisory_xact_lock(7261103)::text`;
      const definition = await tx.nodeTypeDefinition.findUnique({
        where: { key: params.nodeTypeKey },
        include: { policy: true },
      });
      if (!definition)
        throw new NodeTypePolicyError(
          'NODE_TYPE_NOT_FOUND',
          'Node type not found',
        );
      const current: NodeTypePolicySnapshot = definition.policy ?? {
        nodeTypeKey: definition.key,
        isCatalogVisible: true,
        isExecutionAllowed: true,
        revision: 0,
        updatedAt: definition.updatedAt,
