+} satisfies Record<AdminAuditAction, string>;
+function isObject(value: unknown): value is Record<string, unknown> {
+  return value !== null && typeof value === 'object' && !Array.isArray(value);
+}
+export function projectAdminAuditSnapshot(action: AdminAuditSummary['action'], targetType: AdminAuditSummary['targetType'], value: unknown): AdminAuditSnapshot {
+  const result: AdminAuditSnapshot = {};
+  if (action === 'UNKNOWN_ACTION' || targetByAction[action] !== targetType || !isObject(value)) return result;
+  for (const field of fieldsByAction[action]) {
+    if (!Object.hasOwn(value, field)) continue;
+    const entry = value[field];
+    if (entry === null) result[field] = null;
+    else if (field === 'role') {
+      if (entry === 'ADMIN' || entry === 'CLIENT') result[field] = entry;
+    } else if (field === 'revision') {
+      if (typeof entry === 'number' && Number.isSafeInteger(entry) && entry >= 0) result[field] = entry;
+    } else if (typeof entry === 'boolean') result[field] = entry;
+  }
+  return result;
